<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Composition with Red, Blue and Yellow (1930) | Piet Mondrian and De Stijl</title>
<meta name="description" content="The story of Piet Mondrian's 1930 painting: a few primary-colour blocks, thick black lines, and an asymmetric balance that became a reference for modern graphic design and architecture.">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Archivo:wdth,wght@62..125,400..900&display=swap" rel="stylesheet">
<style>
  :root {
    --red: #d3201f;
    --blue: #17479e;
    --yellow: #f7c900;
    --white: #f8f6ef;
    --grey: #c9c8c3;
    --black: #0b0b0b;
    --line: clamp(8px, 1vw, 14px);
    --pad: clamp(1.1rem, 2.4vw, 2.5rem);
  }
  * { box-sizing: border-box; margin: 0; }
  html { scroll-behavior: smooth; }
  body {
    background: var(--black);
    color: var(--black);
    font: 400 clamp(1.05rem, 1.25vw, 1.25rem)/1.5 Archivo, "Helvetica Neue", Arial, sans-serif;
  }
  a { color: inherit; }
  :focus-visible { outline: 4px solid var(--black); outline-offset: 3px; box-shadow: 0 0 0 3px var(--white); }

  /* The black page shows through the gaps, so every gap is a Mondrian line. */
  .mondrian-grid { display: grid; gap: var(--line); border-bottom: var(--line) solid var(--black); }
  .cell { background: var(--white); padding: var(--pad); min-width: 0; }
  .cell--red { background: var(--red); color: var(--white); }
  .cell--blue { background: var(--blue); color: var(--white); }
  .cell--yellow { background: var(--yellow); }
  .cell--grey { background: var(--grey); }

  .label {
    font-stretch: 112%;
    font-weight: 700;
    font-size: .8rem;
    letter-spacing: .08em;
    text-transform: uppercase;
    line-height: 1.3;
  }
  h1, h2, .display {
    font-stretch: 75%;
    font-weight: 900;
    line-height: .92;
    letter-spacing: -.01em;
    text-transform: uppercase;
  }
  h2 { font-size: clamp(2.6rem, 6vw, 6rem); }
  p { max-width: 54ch; }
  p + p { margin-top: .9em; }

  /* Hero: the page opens as the picture, red top right, blue bottom left, yellow bottom right. */
  .hero {
    min-height: 100svh;
    grid-template-columns: minmax(150px, 2fr) 5fr minmax(170px, 2.4fr);
    grid-template-rows: 1fr 1.5fr minmax(190px, .9fr);
    grid-template-areas:
      "painter title title"
      "year    title title"
      "blue    cta   yellow";
  }
  .hero__painter { grid-area: painter; display: flex; flex-direction: column; justify-content: space-between; gap: 1rem; }
  .hero__painter strong { font-size: 1.35em; font-stretch: 75%; font-weight: 800; line-height: 1.05; text-transform: uppercase; display: block; }
  .hero__year { grid-area: year; display: flex; align-items: flex-end; }
  .hero__year span { font-size: clamp(3rem, 6.4vw, 6.6rem); }
  .hero__title { grid-area: title; display: flex; flex-direction: column; justify-content: space-between; gap: 2rem; }
  h1 { font-size: clamp(3.1rem, 9.4vw, 10.5rem); }
  h1 span { display: block; }
  .hero__blue { grid-area: blue; display: flex; align-items: flex-end; }
  .hero__yellow { grid-area: yellow; display: flex; align-items: flex-end; }
  .hero__cta { grid-area: cta; display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 1.25rem 2rem; }
  .hero__cta p { flex: 1 1 19rem; }

  .button {
    display: inline-block;
    padding: .95em 1.4em;
    background: var(--black);
    color: var(--white);
    border: 5px solid var(--black);
    font-stretch: 112%;
    font-weight: 800;
    font-size: .95rem;
    letter-spacing: .04em;
    text-decoration: none;
    text-transform: uppercase;
    transition: background-color .15s, color .15s;
  }
  .button:hover { background: var(--yellow); color: var(--black); }
  .cell--yellow .button:hover { background: var(--white); }

